import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"豆包教程","description":"打开豆包网页或桌面客户端，发出第一句。只复述能在官方页核对的入口和能力。","frontmatter":{"title":"豆包教程","description":"打开豆包网页或桌面客户端，发出第一句。只复述能在官方页核对的入口和能力。","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/doubao/doubao.md","filePath":"zh/products/doubao/doubao.md","lastUpdated":1787110548000}'),d={name:"zh/products/doubao/doubao.md"};function l(n,a,h,s,i,c){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="豆包教程" tabindex="-1">豆包教程 <a class="header-anchor" href="#豆包教程" aria-label="Permalink to &quot;豆包教程&quot;">​</a></h1><blockquote><p>先打开 <a href="https://www.doubao.com/" target="_blank" rel="noreferrer">doubao.com</a> 或 <a href="https://www.doubao.com/download/desktop" target="_blank" rel="noreferrer">桌面下载页</a>。本页只复述能在官方页核对的入口。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 第一次用豆包的前端工程师。</p><p><strong>你会完成：</strong> 在网页或客户端里发出第一句；知道桌面页比首页多写了什么。</p><p><strong>不会做：</strong> Trae 安装、方舟 API、扣子编排、编造会员价。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>能打开 <code>doubao.com</code>。部分网络会把该域名解析到 <code>198.18.0.0/15</code>，先换 DNS / 关 Fake-IP 再判断「打不开」。</li><li>部分区域首页会提示先登录，或改用 <strong>Dola</strong>。Dola 不是本教程对象。</li></ul><h2 id="_15-分钟内打开" tabindex="-1">15 分钟内打开 <a class="header-anchor" href="#_15-分钟内打开" aria-label="Permalink to &quot;15 分钟内打开&quot;">​</a></h2><h3 id="_1-选一个官方入口" tabindex="-1">1. 选一个官方入口 <a class="header-anchor" href="#_1-选一个官方入口" aria-label="Permalink to &quot;1. 选一个官方入口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>端</th><th>怎么走</th><th>来源</th></tr></thead><tbody><tr><td>网页</td><td>打开 <a href="https://www.doubao.com/" target="_blank" rel="noreferrer">doubao.com</a>，登录后提问</td><td>首页</td></tr><tr><td>网页（桌面落地页）</td><td><a href="https://www.doubao.com/download/desktop" target="_blank" rel="noreferrer">download/desktop</a> 点 <strong>使用网页版</strong></td><td>桌面页</td></tr><tr><td>Windows / macOS</td><td><a href="https://www.doubao.com/download/" target="_blank" rel="noreferrer">download</a> 或桌面页 <strong>下载豆包桌面版</strong></td><td>官方下载</td></tr><tr><td>Windows 商店</td><td>Microsoft Store 应用「豆包」，id <code>XPDDTBMM6TZ365</code></td><td><a href="https://apps.microsoft.com/detail/xpddtbmm6tz365" target="_blank" rel="noreferrer">商店页</a></td></tr><tr><td>Android</td><td>应用宝包名 <code>com.larus.nova</code>（开发者：北京春田知韵科技有限公司）</td><td><a href="https://sj.qq.com/appdetail/com.larus.nova" target="_blank" rel="noreferrer">应用宝</a></td></tr></tbody></table><p>系统最低版本官方下载页 2026-08-19 <strong>没有</strong>在无 JS 抓取里给出数字。 以安装包页为准。</p><h3 id="_2-发出第一句" tabindex="-1">2. 发出第一句 <a class="header-anchor" href="#_2-发出第一句" aria-label="Permalink to &quot;2. 发出第一句&quot;">​</a></h3><p>登录后在输入框提问。首页把豆包定位成聊天、写作、文案、翻译、编程工具。把它当对话助手用，不要期待它克隆仓库、开 PR。</p><h3 id="_3-桌面版多写了什么" tabindex="-1">3. 桌面版多写了什么 <a class="header-anchor" href="#_3-桌面版多写了什么" aria-label="Permalink to &quot;3. 桌面版多写了什么&quot;">​</a></h3><p>只在需要本地生产力时装客户端。官方桌面页原文：</p><ul><li>「日常工作可高效写作翻译、一键生成PPT、智能处理Excel 数据」</li><li>「创意创作依托专业版Seedream 5.0 生图，专业版Seedance 2.5 生视频核心模型」</li><li>「内置自主规划执行的 Agent 智能体，自动统筹多类任务」</li></ul><p>逐步点击路径官方没有文档树，本页不编。</p><h2 id="官方能力-按出处分组" tabindex="-1">官方能力（按出处分组） <a class="header-anchor" href="#官方能力-按出处分组" aria-label="Permalink to &quot;官方能力（按出处分组）&quot;">​</a></h2><h3 id="首页-下载页-meta-在说什么" tabindex="-1">首页 / 下载页 meta 在说什么 <a class="header-anchor" href="#首页-下载页-meta-在说什么" aria-label="Permalink to &quot;首页 / 下载页 meta 在说什么&quot;">​</a></h3><blockquote><p>Seedance 2.0 视频生成模型现已全面接入 豆包 ，现在登录即可免费使用！</p></blockquote><blockquote><p>豆包 是你的 AI 聊天智能对话问答助手，写作文案翻译编程工具。</p></blockquote><h3 id="桌面落地页在说什么" tabindex="-1">桌面落地页在说什么 <a class="header-anchor" href="#桌面落地页在说什么" aria-label="Permalink to &quot;桌面落地页在说什么&quot;">​</a></h3><p><a href="https://www.doubao.com/download/desktop" target="_blank" rel="noreferrer">download/desktop</a> 把同一产品写成「全链路 AI 生产力」，并点名 <strong>Seedream 5.0</strong>、<strong>Seedance 2.5</strong>、<strong>Agent 智能体</strong>。</p><p><strong>两份官方页的视频模型版本号不一致。</strong> 本站并列引用，不宣布哪一个「才算现行」。</p><h3 id="和编程相关的边界" tabindex="-1">和编程相关的边界 <a class="header-anchor" href="#和编程相关的边界" aria-label="Permalink to &quot;和编程相关的边界&quot;">​</a></h3><p>官方把「编程」写在助手能力里。仓库级、带 diff / 终端的编码去 <a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a>（本站 #80）。在自己的服务里调豆包模型去 <a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">火山方舟</a>（本站 #82）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>回查入口：<a href="./doubao-cheatsheet.html">速查表</a></li><li>分清同厂名字：<a href="./doubao-glossary.html">术语表</a></li><li>模型内部：<a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a></li></ul>',29)])])}const _=t(d,[["render",l]]);export{f as __pageData,_ as default};
